/**
 * 3D Dandiya Clash Rhythm Mini-Game
 * Interactive overlay with dual Dandiya sticks clashing to the beat
 */

import { audio } from '../core/audio.js';
import confetti from 'canvas-confetti';

export class DandiyaClashGame {
  constructor() {
    this.isActive = false;
    this.combo = 0;
    this.score = 0;
    this.highScore = parseInt(localStorage.getItem('dandiya_highscore') || '0', 10);
    this.el = null;

    this.build();
  }

  build() {
    this.el = document.createElement('div');
    this.el.className = 'dandiya-clash-overlay';
    this.el.id = 'dandiya-clash-overlay';
    this.el.setAttribute('aria-hidden', 'true');

    this.el.innerHTML = `
      <div class="clash-hud">
        <div class="clash-stats">
          <div class="stat-pill"><span class="stat-label">COMBO</span> <span class="stat-val combo-val" id="clash-combo">0x</span></div>
          <div class="stat-pill"><span class="stat-label">SCORE</span> <span class="stat-val" id="clash-score">0</span></div>
          <div class="stat-pill"><span class="stat-label">BEST</span> <span class="stat-val" id="clash-best">${this.highScore}</span></div>
        </div>
        <div class="clash-feedback" id="clash-feedback">TAP OR PRESS SPACE ON THE DHOL BEAT!</div>
        <button class="clash-exit-btn" id="clash-exit" title="Exit Dandiya Clash">✕ Exit</button>
      </div>

      <!-- Animated Dandiya Sticks in Hand -->
      <div class="dandiya-stage" id="dandiya-stage">
        <div class="stick stick-left" id="stick-left">
          <div class="stick-shaft"></div>
          <div class="stick-tassel"></div>
        </div>
        <div class="clash-spark" id="clash-spark"></div>
        <div class="stick stick-right" id="stick-right">
          <div class="stick-shaft"></div>
          <div class="stick-tassel"></div>
        </div>
      </div>

      <div class="clash-tap-hint">
        <span>Click anywhere or tap [SPACEBAR] to Strike Dandiya!</span>
      </div>
    `;

    document.body.appendChild(this.el);

    // Bindings
    this.el.querySelector('#clash-exit').addEventListener('click', () => this.toggle());

    this.el.addEventListener('pointerdown', (e) => {
      if (e.target.id === 'clash-exit') return;
      this.strikeDandiya();
    });

    window.addEventListener('keydown', (e) => {
      if (e.code === 'Space' && this.isActive) {
        e.preventDefault();
        this.strikeDandiya();
      }
    });
  }

  toggle() {
    this.isActive = !this.isActive;
    this.el.classList.toggle('show', this.isActive);
    this.el.setAttribute('aria-hidden', !this.isActive ? 'true' : 'false');

    if (this.isActive) {
      this.combo = 0;
      this.score = 0;
      this.updateHud();
    }
  }

  strikeDandiya() {
    if (!this.isActive) return;

    // Play tactile sound
    audio.playDandiya(0.7);

    // Visual strike animation
    const stage = this.el.querySelector('#dandiya-stage');
    const spark = this.el.querySelector('#clash-spark');
    const feedback = this.el.querySelector('#clash-feedback');

    stage.classList.remove('striking');
    void stage.offsetWidth; // trigger reflow
    stage.classList.add('striking');

    spark.classList.remove('flash');
    void spark.offsetWidth;
    spark.classList.add('flash');

    // Combo & Score
    this.combo++;
    const points = 10 * Math.max(1, Math.floor(this.combo / 4));
    this.score += points;

    if (this.score > this.highScore) {
      this.highScore = this.score;
      localStorage.setItem('dandiya_highscore', this.highScore.toString());
    }

    // Feedback slogans
    const slogans = [
      'WAH KHELAIYA! 🎉',
      'SUPER CLACK! ⚡',
      'GARBA FEVER! 💃',
      'PERFECT BEAT! 🥁',
      'RANGTALI! ✨',
      'DHOLIDA DHOL! 🔥'
    ];
    feedback.textContent = slogans[this.combo % slogans.length];

    // Milestone confetti
    if (this.combo > 0 && this.combo % 15 === 0) {
      confetti({
        particleCount: 50,
        spread: 60,
        origin: { y: 0.5 }
      });
    }

    this.updateHud();
  }

  updateHud() {
    this.el.querySelector('#clash-combo').textContent = `${this.combo}x`;
    this.el.querySelector('#clash-score').textContent = this.score.toLocaleString();
    this.el.querySelector('#clash-best').textContent = this.highScore.toLocaleString();
  }
}
